/* 1. job task rows */
rows('Get Tasks').forEach(r=>{const job=S(r.job_no);if(job&&!want(job))return;if(!job&&ONE)return;const ji=job?jobInfo(job):{mode:'',type:'',stage:'',on:[],site:''};if(ji.stage==='Closed'&&!ONE)return;
 const req=S(r.req)||'custom',d=pj(r.data_json),x=JRK[jk(job)+'|task'+r.id],MS=S(r.status);let st;
 if(FINAL.test(MS))st=d.verified_by?'Verified':'Done';
 else if(x)st=x.st==='pending'?'In progress':'To do';
 else if(!job||ji.stage!=='Job'||req==='custom'||ji.on.indexOf(req)<0||SCHED[req])st=START.test(MS)?'To do':'In progress';
