 const t={key:'jobreq:'+job+':task'+r.id,src:'row',id:r.id,job:job,site:ji.site,type:ji.type,stage:S(r.stage)||(ENQ[req]?'Enquiry':(ji.stage||'')),category:S(r.category)||CAT[req]||(job?'Site':'Office'),title:title,status:st,auto:auto&&st==='Done'&&!FINAL.test(MS),due:S(r.due_on).slice(0,10),assignee:S(r.assignee),req:req,ref_name:S(r.ref_name),note:x?S(x.note):'',desc:S(r.notes),checklist:Array.isArray(d.checklist)?d.checklist:[],pin:d.pin||null,tags:S(d.tags),files:S(r.files_json),created_by:S(r.created_by),created_at:S(r.created_at),done_by:S(r.done_by),done_at:S(r.done_at),verified_by:S(d.verified_by),link:x?S(x.link):(job?'/webhook/cbs-job-file?job='+encodeURIComponent(job):''),al:x?S(x.al):''};
 overlay(t);od(t);out.push(t);});
/* 2. requirement checks, enquiry checklist and roll-ups from the reqs feed (only open ones come back) */
JR.forEach(x=>{const job=S(x.job),k=S(x.k);if(!job||!want(job))return;if(/^task\d+$/.test(k))return;const ji=jobInfo(job);
 let src='req',cat=CAT[k]||'Site',stg=ENQ[k]?'Enquiry':(ji.stage||'Job');
 if(k.indexOf('enqt')===0){src='enq';cat='Enquiry';stg='Enquiry';}else if(ROLL[k]){src='roll';cat=ROLL[k];}
 const t={key:'jobreq:'+job+':'+k,src:src,id:k,job:job,site:S(x.site)||ji.site,type:ji.type,stage:stg,category:cat,title:S(x.l).replace(/^Enquiry task: /,''),status:x.st==='pending'?'In progress':'To do',auto:src!=='enq',due:'',assignee:'',req:src==='req'?k:'',note:S(x.note),tx:S(x.tx),link:S(x.link),al:S(x.al),urg:!!x.urg};
