const ET={survey:'Site survey',estimate:'Estimate',drawings:'RFIs (info from client)',supq:'Supplier quotes',subq:'Subcontractor quotes',docs:'Documentation (we supply)',programme:'Programme'};
const dmy=v=>{const m=S(v).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?m[3]+'/'+m[2]:''};
