 else if(k==='estimate'){const es=e.estimate||{},v=S(st.estimate)||'Not started';due=S(es.due).slice(0,10);if(v==='Complete'){s='Done';note='Estimate complete';due='';}else{if(v!=='Not started')s='In progress';note=v+(S(es.by)?' \u00b7 '+S(es.by):'')+(due?' \u00b7 due '+dmy(due):'');}}
