 else if(k==='supq'||k==='subq'){const R=L(k==='supq'?e.quotes:e.subquotes);const dn=x=>!!(S(x.received_on)||L(x.files).length||S(x.status));if(!R.length)note='No quotes added yet';else if(R.every(dn)){s='Done';note=R.length+' received';}else{s='In progress';note=R.filter(dn).length+' of '+R.length+' received';}}
 else if(k==='programme'){const v=S(st.programme)||'Not started';if(v==='Draft ready'){s='Done';note='Draft ready';}else{if(v!=='Not started')s='In progress';note=v;}}
 return {s,note,due};}
