 const dn=st==='Done',fl=(Array.isArray(c.files)?c.files:(Array.isArray(o.files)?o.files:[])).slice(-20).map(fileOf).filter(f=>f.u);
 return {cid:/^[0-9a-z]{4,16}$/.test(S(c.cid))?S(c.cid):Math.random().toString(36).slice(2,10),t:S(c.t).slice(0,200),st:st,done:dn,
  by:dn?(S(c.by)||(o.done?S(o.by):'')||by).slice(0,60):'',at:dn?(date(c.at)||(o.done?date(o.at):'')||today):'',who:S(c.who).slice(0,80),due:date(c.due),nt:S(c.nt).slice(0,2000),files:fl};}
