 if(x.checklist!==undefined){const OLD={};(Array.isArray(d.checklist)?d.checklist:[]).forEach(c=>{if(c&&c.cid)OLD[c.cid]=c;});
  d.checklist=(Array.isArray(x.checklist)?x.checklist:[]).slice(0,60).map(c=>cline(c,OLD[S(c&&c.cid)])).filter(c=>c.t);}
