 if(x.link!==undefined){const L=x.link||{};if(['claim','inc','veh','plant'].indexOf(S(L.type))>-1&&(S(L.id)||S(L.type)==='claim'||S(L.type)==='inc'))d.link={type:S(L.type),id:S(L.id).slice(0,40),name:S(L.name).slice(0,200)};else delete d.link;}
