 if(x.pin!==undefined)d.pin=x.pin&&x.pin.drawing_id?{drawing_id:S(x.pin.drawing_id),page:Number(x.pin.page)||1,x:Number(x.pin.x)||0,y:Number(x.pin.y)||0}:null;
 return d;}
const pj=v=>{try{const o=JSON.parse(S(v)||'{}');return o&&typeof o==='object'?o:{};}catch(e){return {};}};
