/* Job files (Option A step 2): every file in the job's SharePoint folders, grouped by folder.
   Jobs/Job N/<folder>/... (Job File uploads, one Graph call per folder) plus Enquiries/Job N/... (Enquiry prep uploads, grouped by the kind in the file name). */
const S=v=>v==null?'':String(v).trim();
const job=$('Files Prep').first().json.job;
const KIND={'Survey':'Surveys','Drawings':'Drawings','Estimate':'Estimate','Supplier quote':'Quotes','Subcontractor quote':'Quotes','Documentation':'Documentation','Drawings spec':'Drawings'};
function file(x,folder,src){return {n:S(x.name),u:S(x.webUrl),id:S(x.id),size:Number(x.size)||0,at:S(x.lastModifiedDateTime),by:S(x.lastModifiedBy&&x.lastModifiedBy.user&&x.lastModifiedBy.user.displayName),mime:S(x.file&&x.file.mimeType),folder:folder,src:src};}
const F={};function add(f){(F[f.folder]=F[f.folder]||[]).push(f);}
const J=$('Graph Jobs').first().json||{};
(Array.isArray(J.value)?J.value:[]).forEach(x=>{if(x.file)add(file(x,'Other','job'));});
const FI=$('Folder Items').all().map(i=>i.json),FG=$('Graph Folder').all().map(i=>i.json);
FI.forEach((f,i)=>{if(!f.id)return;const name=S(f.name);F[name]=F[name]||[];const r=FG[i]||{};(Array.isArray(r.value)?r.value:[]).forEach(c=>{if(c.file)add(file(c,name,'job'));else if(c.folder)add({n:S(c.name)+' (folder)',u:S(c.webUrl),id:S(c.id),size:0,at:S(c.lastModifiedDateTime),by:'',mime:'folder',folder:name,src:'job'});});});
const Q=$('Graph Enq').first().json||{};
(Array.isArray(Q.value)?Q.value:[]).forEach(x=>{if(x.file){const m=S(x.name).match(/^Job [^-]+ - ([^-]+?) - /);add(file(x,KIND[m&&m[1]]||'Enquiry','enq'));}});
Object.keys(F).forEach(k=>F[k].sort((a,b)=>b.at.localeCompare(a.at)));
const ORDER=['Surveys','Drawings','Estimate','Quotes','Documentation','RAMS','Subcontractor RAMS','Purchase orders','Permits','Photos','Handover'];
const folders=Object.keys(F).sort((a,b)=>{const ia=ORDER.indexOf(a),ib=ORDER.indexOf(b);return (ia<0?99:ia)-(ib<0?99:ib)||a.localeCompare(b);}).map(k=>({name:k,files:F[k]}));
return [{json:{ok:true,job:job,folders:folders,count:folders.reduce((n,f)=>n+f.files.filter(x=>x.mime!=='folder').length,0),upload_folders:Array.from(new Set(ORDER.concat(folders.filter(f=>f.files.some(x=>x.src==='job')).map(f=>f.name)).concat(['Other'])))}}];

/* POST cbs-job-files-up {job, folder, filename, data (base64 / data URL), by[, office]}: one file into Jobs/Job N/<folder> on SharePoint,
   or Office Tasks/<folder> when office is set and there is no job (tasks on the Actions board that are not on a job). Max 10 MB. */
const b=$input.first().json.body||{};const S=(v,n)=>String(v==null?'':v).trim().slice(0,n||200);
const job=S(b.job,20).replace(/^#/,'');const folder=S(b.folder,60).replace(/[\\/:*?"<>|#%]+/g,' ').replace(/\s{2,}/g,' ').trim();
let data=S(b.data,20000000);const mm=data.match(/^data:([^;,]+)[;,]/);const mime=mm?mm[1]:'application/octet-stream';data=data.replace(/^data:[^,]*,/,'');
const office=!job&&!!b.office;let err='';if(!office&&!/^[A-Za-z0-9-]{1,20}$/.test(job))err='Job number missing.';else if(!folder)err='Pick a folder.';else if(!data)err='No file received.';else if(data.length>14000000)err='That file is over 10 MB.';
if(err)return [{json:{valid:false,error:err}}];
