const r=$input.first().json||{},p=$('Files Up Prep').first().json;
if(!r.webUrl)return [{json:{ok:false,error:'The SharePoint upload failed. Try again.'}}];
return [{json:{ok:true,n:String(r.name||p.name),u:String(r.webUrl),id:String(r.id||''),folder:p.folder}}];

/* one item per sub-folder of Jobs/Job N, so Graph Folder lists each folder's files */
const J=$input.first().json||{};const F=(Array.isArray(J.value)?J.value:[]).filter(x=>x.folder&&x.id).map(x=>({json:{id:x.id,name:x.name}}));
return F.length?F:[{json:{id:'',name:''}}];

/* GET cbs-job-details?job=N: the job's details from cbs_jobs (newest row for the job number). */
const S=v=>v==null?'':String(v).trim();const jk=v=>S(v).replace(/[^0-9A-Za-z]/g,'').toLowerCase();
const job=S(($('Details Hook').first().json.query||{}).job).replace(/[^0-9A-Za-z-]/g,'');
const r=$input.all().map(i=>i.json).filter(x=>x&&x.id!=null&&jk(x.ref)===jk(job)).sort((a,b)=>Number(b.id)-Number(a.id))[0];
const F=['name','client','client_contact','site','starts_on','ends_on','pm','scope','contract_value','notes'];
