['name','client','client_contact','site','pm','scope','notes'].forEach(k=>{o[k]=d[k]!==undefined?S(d[k],L[k]):S(r[k],L[k]);});
['starts_on','ends_on'].forEach(k=>{const v=d[k]!==undefined?S(d[k],10):S(r[k],10);o[k]=/^\d{4}-\d{2}-\d{2}$/.test(v)?v:'';});
